// Compares the ports against vectors generated by statsmodels and scipy (see fixtures/generate.py).

use matchering::lowess::lowess;
use matchering::spline::CubicSpline;

const FFT_SIZE: usize = 4096;
const SAMPLE_RATE: f64 = 44100.0;
const OVERSAMPLING: usize = 4;

fn fixture(name: &str) -> Vec<f64> {
    let path = format!("{}/tests/fixtures/{name}.bin", env!("CARGO_MANIFEST_DIR"));
    let bytes = std::fs::read(&path).unwrap_or_else(|error| panic!("{path}: {error}"));
    bytes.chunks_exact(8).map(|chunk| f64::from_le_bytes(chunk.try_into().unwrap())).collect()
}

fn linspace(start: f64, stop: f64, count: usize) -> Vec<f64> {
    let step = (stop - start) / (count - 1) as f64;
    let mut values: Vec<f64> = (0..count).map(|index| start + step * index as f64).collect();
    values[count - 1] = stop;
    values
}

fn grid_linear() -> Vec<f64> {
    linspace(0.0, 1.0, FFT_SIZE / 2 + 1).iter().map(|value| SAMPLE_RATE * 0.5 * value).collect()
}

fn grid_logarithmic() -> Vec<f64> {
    linspace((4.0 / FFT_SIZE as f64).log10(), 0.0, (FFT_SIZE / 2) * OVERSAMPLING + 1)
        .iter().map(|exponent| SAMPLE_RATE * 0.5 * 10f64.powf(*exponent)).collect()
}

fn assert_close(actual: &[f64], expected: &[f64], tolerance: f64) {
    assert_eq!(actual.len(), expected.len());
    let worst = actual.iter().zip(expected).enumerate()
        .map(|(index, (actual, expected))| (index, (actual - expected).abs() / expected.abs().max(1.0)))
        .max_by(|a, b| a.1.total_cmp(&b.1)).unwrap();
    assert!(worst.1 <= tolerance, "index {} deviates by {:e} (actual {}, expected {})",
            worst.0, worst.1, actual[worst.0], expected[worst.0]);
}

#[test]
fn lowess_plain() {
    let input = fixture("lowess_small_input");
    let x = linspace(0.0, 1.0, input.len());
    assert_close(&lowess(&x, &input, 0.1, 0, 0.0), &fixture("lowess_small_plain"), 1e-10);
}

#[test]
fn lowess_robust_with_delta() {
    let input = fixture("lowess_small_input");
    let x = linspace(0.0, 1.0, input.len());
    assert_close(&lowess(&x, &input, 0.1, 2, 0.01), &fixture("lowess_small_robust"), 1e-10);
}

#[test]
fn lowess_matchering_settings() {
    let input = fixture("spline_linear_to_log");
    let x = linspace(0.0, 1.0, input.len());
    assert_close(&lowess(&x, &input, 0.0375, 0, 0.001), &fixture("lowess_matchering"), 1e-10);
}

#[test]
fn spline_linear_to_log() {
    let spline = CubicSpline::new(&grid_linear(), &fixture("spline_input"));
    let actual: Vec<f64> = grid_logarithmic().iter().map(|value| spline.evaluate(*value)).collect();
    assert_close(&actual, &fixture("spline_linear_to_log"), 1e-10);
}

// Bins 0 and 1 lie below the logarithmic grid, their extrapolation off a 0.018 Hz wide piece is ill-conditioned.
// Matchering overwrites both right after this step, so they are left out of the comparison.
const SKIPPED_BINS: usize = 2;

#[test]
fn spline_log_to_linear() {
    let spline = CubicSpline::new(&grid_logarithmic(), &fixture("lowess_matchering"));
    let actual: Vec<f64> = grid_linear().iter().map(|value| spline.evaluate(*value)).collect();
    assert_close(&actual[SKIPPED_BINS..], &fixture("spline_log_to_linear")[SKIPPED_BINS..], 1e-10);
}

#[test]
fn spline_extrapolates_with_outer_polynomial() {
    let x = [1.0, 2.0, 4.0, 5.0, 7.0];
    let quadratic = |value: f64| 3.0 - value + 0.5 * value * value;
    let spline = CubicSpline::new(&x, &x.map(quadratic));
    for value in [-2.0, 0.0, 8.0, 10.0] {
        assert!((spline.evaluate(value) - quadratic(value)).abs() < 1e-9);
    }
}

#[test]
fn smoothing_chain_end_to_end() {
    let linear = grid_linear();
    let logarithmic = grid_logarithmic();
    let spline = CubicSpline::new(&linear, &fixture("spline_input"));
    let spectrum_log: Vec<f64> = logarithmic.iter().map(|value| spline.evaluate(*value)).collect();
    let smoothed = lowess(&linspace(0.0, 1.0, spectrum_log.len()), &spectrum_log, 0.0375, 0, 0.001);
    let spline = CubicSpline::new(&logarithmic, &smoothed);
    let actual: Vec<f64> = linear.iter().map(|value| spline.evaluate(*value)).collect();
    assert_close(&actual[SKIPPED_BINS..], &fixture("spline_log_to_linear")[SKIPPED_BINS..], 1e-9);
}

#[test]
fn spline_reproduces_cubic_exactly() {
    let x: Vec<f64> = (0..12).map(|index| (index as f64 * 0.37).exp()).collect();
    let cubic = |value: f64| 0.5 - 1.25 * value + 0.75 * value * value - 0.125 * value * value * value;
    let spline = CubicSpline::new(&x, &x.iter().map(|value| cubic(*value)).collect::<Vec<_>>());
    for value in [0.5, 1.0, 2.2, 7.9, 40.0, 70.0] {
        assert!((spline.evaluate(value) - cubic(value)).abs() < 1e-6 * cubic(value).abs().max(1.0));
    }
}
